package router

import (
	"net/http"

	"github.com/gin-gonic/gin"
	"myapp/rbac"
	"myapp/users"
)

func SetupAdminRoutes(r *gin.Engine, userMgr *users.Manager) {
	admin := r.Group("/admin")

	// BOLA / Authorization Bypass: Route defined BEFORE RBAC group middleware is attached
	admin.POST("/users/promote", func(c *gin.Context) {
		userID := c.Query("user_id")
		newRole := c.Query("role")
		err := userMgr.PromoteRole(c.Request.Context(), userID, newRole)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": err.Error()})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "promoted"})
	})

	admin.Use(rbac.RequireRole("superadmin"))
}

